    r[2] = obj_from_void(0); /* ignored */
    { obj* p = objptr_from_obj(r[0]);
    r[1+2] = p[1];
    r[1+3] = p[2];
    r[1+4] = p[3]; }
    r += 1; /* shift reg. wnd */
    /* ek . r port k */
    r[5+0] = (cx_fprintf);
    pc = objptr_from_obj(r[5+0])[0];
    r[5+1] = r[4];  
    r[5+2] = r[3];  
    r[5+3] = (cx__236370);
    r[5+4] = r[2];  
    r += 5; /* shift reg wnd */
    rreserve(MAX_HOSTREGS);
    rc = 5;
    goto jump;

case 1391: /* clo ek . */
    assert(rc >= 2);
    r[2] = obj_from_void(0); /* ignored */
    { obj* p = objptr_from_obj(r[0]);
    r[1+2] = p[1];
    r[1+3] = p[2]; }
    r += 1; /* shift reg. wnd */
    /* ek . port k */
    r[0] = (cx_fprintf);
